custom_schema.body:
{
    "schema_version": 1,
    "json_schema": {
        "builder": {
            "$defs": {
                "AllGroup": {
                    "additionalProperties": false,
                    "properties": {
                        "all": {
                            "description": "AND: every child is true",
                            "items": {
                                "oneOf": [
                                    {
                                        "$ref": "#/$defs/AllGroup"
                                    },
                                    {
                                        "$ref": "#/$defs/AnyGroup"
                                    },
                                    {
                                        "$ref": "#/$defs/CompareCondition"
                                    },
                                    {
                                        "$ref": "#/$defs/BetweenCondition"
                                    },
                                    {
                                        "$ref": "#/$defs/TrendCondition"
                                    }
                                ]
                            },
                            "minItems": 1,
                            "title": "All",
                            "type": "array"
                        }
                    },
                    "required": [
                        "all"
                    ],
                    "title": "AllGroup",
                    "type": "object"
                },
                "AnyGroup": {
                    "additionalProperties": false,
                    "properties": {
                        "any": {
                            "description": "OR: at least one child is true",
                            "items": {
                                "oneOf": [
                                    {
                                        "$ref": "#/$defs/AllGroup"
                                    },
                                    {
                                        "$ref": "#/$defs/AnyGroup"
                                    },
                                    {
                                        "$ref": "#/$defs/CompareCondition"
                                    },
                                    {
                                        "$ref": "#/$defs/BetweenCondition"
                                    },
                                    {
                                        "$ref": "#/$defs/TrendCondition"
                                    }
                                ]
                            },
                            "minItems": 1,
                            "title": "Any",
                            "type": "array"
                        }
                    },
                    "required": [
                        "any"
                    ],
                    "title": "AnyGroup",
                    "type": "object"
                },
                "BetweenCondition": {
                    "additionalProperties": false,
                    "properties": {
                        "op": {
                            "const": "between",
                            "title": "Op",
                            "type": "string"
                        },
                        "value": {
                            "oneOf": [
                                {
                                    "$ref": "#/$defs/IndicatorOperand"
                                },
                                {
                                    "$ref": "#/$defs/PriceOperand"
                                },
                                {
                                    "$ref": "#/$defs/ConstantOperand"
                                }
                            ],
                            "title": "Value"
                        },
                        "lower": {
                            "oneOf": [
                                {
                                    "$ref": "#/$defs/IndicatorOperand"
                                },
                                {
                                    "$ref": "#/$defs/PriceOperand"
                                },
                                {
                                    "$ref": "#/$defs/ConstantOperand"
                                }
                            ],
                            "title": "Lower"
                        },
                        "upper": {
                            "oneOf": [
                                {
                                    "$ref": "#/$defs/IndicatorOperand"
                                },
                                {
                                    "$ref": "#/$defs/PriceOperand"
                                },
                                {
                                    "$ref": "#/$defs/ConstantOperand"
                                }
                            ],
                            "title": "Upper"
                        }
                    },
                    "required": [
                        "op",
                        "value",
                        "lower",
                        "upper"
                    ],
                    "title": "BetweenCondition",
                    "type": "object"
                },
                "CompareCondition": {
                    "additionalProperties": false,
                    "properties": {
                        "left": {
                            "oneOf": [
                                {
                                    "$ref": "#/$defs/IndicatorOperand"
                                },
                                {
                                    "$ref": "#/$defs/PriceOperand"
                                },
                                {
                                    "$ref": "#/$defs/ConstantOperand"
                                }
                            ],
                            "title": "Left"
                        },
                        "op": {
                            "enum": [
                                ">",
                                "<",
                                ">=",
                                "<=",
                                "crosses_above",
                                "crosses_below"
                            ],
                            "title": "Op",
                            "type": "string"
                        },
                        "right": {
                            "oneOf": [
                                {
                                    "$ref": "#/$defs/IndicatorOperand"
                                },
                                {
                                    "$ref": "#/$defs/PriceOperand"
                                },
                                {
                                    "$ref": "#/$defs/ConstantOperand"
                                }
                            ],
                            "title": "Right"
                        }
                    },
                    "required": [
                        "left",
                        "op",
                        "right"
                    ],
                    "title": "CompareCondition",
                    "type": "object"
                },
                "ConstantOperand": {
                    "additionalProperties": false,
                    "properties": {
                        "type": {
                            "const": "constant",
                            "title": "Type",
                            "type": "string"
                        },
                        "value": {
                            "title": "Value",
                            "type": "number"
                        },
                        "shift": {
                            "default": 0,
                            "description": "value n bars ago",
                            "maximum": 100,
                            "minimum": 0,
                            "title": "Shift",
                            "type": "integer"
                        }
                    },
                    "required": [
                        "type",
                        "value"
                    ],
                    "title": "ConstantOperand",
                    "type": "object"
                },
                "IndicatorOperand": {
                    "additionalProperties": false,
                    "properties": {
                        "type": {
                            "const": "indicator",
                            "title": "Type",
                            "type": "string"
                        },
                        "name": {
                            "description": "an indicator of the catalog",
                            "maxLength": 32,
                            "minLength": 1,
                            "title": "Name",
                            "type": "string"
                        },
                        "params": {
                            "additionalProperties": true,
                            "description": "omitted = default",
                            "title": "Params",
                            "type": "object"
                        },
