                            "description": "value n bars ago",
                            "maximum": 100,
                            "minimum": 0,
                            "title": "Shift",
                            "type": "integer"
                        },
                        "multiplier": {
                            "default": 1.0,
                            "description": "the operand's value times this number (e.g. 1.5 x volume SMA)",
                            "exclusiveMinimum": 0,
                            "maximum": 1000.0,
                            "title": "Multiplier",
                            "type": "number"
                        }
                    },
                    "required": [
                        "type",
                        "name"
                    ],
                    "title": "IndicatorOperand",
                    "type": "object"
                },
                "PriceOperand": {
                    "additionalProperties": false,
                    "properties": {
                        "type": {
