                            "maximum": 1000.0,
                            "title": "Multiplier",
                            "type": "number"
                        }
                    },
                    "required": [
                        "type",
                        "field"
                    ],
                    "title": "PriceOperand",
                    "type": "object"
                },
                "TrendCondition": {
                    "additionalProperties": false,
                    "properties": {
                        "op": {
                            "enum": [
                                "rising",
                                "falling"
                            ],
                            "title": "Op",
                            "type": "string"
                        },
                        "value": {
                            "oneOf": [
                                {
                                    "$ref": "#/$defs/IndicatorOperand"
                                },
